.card.mini { width: 104px; height: 146px; }
.card:hover { transform: translateY(-7px) scale(1.04); box-shadow: 0 12px 22px rgba(0,0,0,.55); z-index: 3; }
.board-row .card:hover { transform: scale(1.05); }
.card.selected { outline: 3px solid var(--gold); transform: translateY(-9px) scale(1.06); }
.card.targetable { outline: 3px dashed #ff5d73; }
.card.unaffordable { filter: saturate(.35) brightness(.82); }
.card.exhausted { filter: saturate(.3) brightness(.75); transform: rotate(-2deg); }
.card.back {
  width: 52px; height: 72px; cursor: default;
  background: repeating-linear-gradient(45deg, #274b8f 0 8px, #1d3868 8px 16px);
  border-color: #0f2148; display: flex; align-items: center; justify-content: center;
}
.card.back:hover { transform: none; }
.back-rune { font-size: 24px; color: #bcd2ff; }

.card-cost {
  position: absolute; top: -8px; left: -8px; width: 30px; height: 30px; z-index: 2;
  border-radius: 50%; background: radial-gradient(circle at 35% 30%, #b8ffe9, #15965f);
  border: 2px solid #0b5c39; color: #06351f; font-weight: bold; font-size: 17px;
  display: flex; align-items: center; justify-content: center;
}
.wind-badge { position: absolute; top: 4px; right: 7px; font-size: 17px; color: var(--wind); }
.card-art {
  height: 52px; margin-top: 8px; border-radius: 6px;
  background: radial-gradient(circle at 50% 40%, color-mix(in srgb, var(--wind) 55%, white), var(--wind));
  color: rgba(255,255,255,.92); font-size: 34px;
  display: flex; align-items: center; justify-content: center;
  text-shadow: 0 2px 5px rgba(0,0,0,.4);
}
.card.mini .card-art { height: 44px; font-size: 29px; }
.card-name { font-size: 13.5px; font-weight: bold; text-align: center; margin-top: 4px; line-height: 1.1; }
.card-text { font-size: 11px; text-align: center; font-style: italic; color: #5a4632; min-height: 15px; margin-top: 2px; }
.card-stats {
  position: absolute; bottom: 5px; left: 7px; right: 7px;
  display: flex; justify-content: space-between; font-size: 16.5px; font-weight: bold;
}
.card-stats .atk { color: #a33327; }
.card-stats .hp { color: #b03060; }
.card-stats.spell-tag { justify-content: center; color: var(--wind); letter-spacing: 2px; font-size: 12.5px; }

.board-empty { font-style: italic; color: rgba(246,234,210,.5); font-size: 15px; }

/* ---------------- animation & feedback ---------------- */

@keyframes dealIn { from { transform: translateY(-46px) rotate(-5deg); opacity: 0; } to { transform: none; opacity: 1; } }
#player-hand .card { animation: dealIn .35s ease both; }

@keyframes popIn { 0% { transform: scale(.6); } 60% { transform: scale(1.12); } 100% { transform: scale(1); } }
.card.just-played { animation: popIn .3s ease; }

@keyframes lungeUp { 40% { transform: translateY(-26px) scale(1.07); } }
@keyframes lungeDown { 40% { transform: translateY(26px) scale(1.07); } }
.card.lunging-up { animation: lungeUp .3s ease; }
.card.lunging-down { animation: lungeDown .3s ease; }

@keyframes shake { 20%, 60% { transform: translateX(-5px); } 40%, 80% { transform: translateX(5px); } }
.hurt { animation: shake .35s ease; filter: brightness(1.4) sepia(.6) hue-rotate(-38deg) saturate(2.4); }

@keyframes dieAway { to { transform: translateY(16px) rotate(7deg) scale(.82); opacity: 0; } }
.card.dying { animation: dieAway .45s ease forwards; }

.floater {
  position: fixed; z-index: 50; font-size: 27px; font-weight: bold; pointer-events: none;
  animation: floatUp 1.05s ease forwards; text-shadow: 0 2px 4px rgba(0,0,0,.75);
}
.floater.dmg { color: #ff6b5e; }
.floater.heal { color: #7be495; }
@keyframes floatUp { to { transform: translateY(-44px); opacity: 0; } }
